// WGo service worker. Generated by integrations/offline.ts — edit sw-template.js, not dist/sw.js.
const VERSION = '__VERSION__';
const PRECACHE = __PRECACHE__;
const CORE = `wgo-core-${VERSION}`;
// Map tiles, map fonts and photos: kept across versions, trimmed when large.
const LAZY = 'wgo-lazy-v1';
const LAZY_MAX_ENTRIES = 1500;
const NETWORK_TIMEOUT = 3500;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CORE)
      .then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('wgo-core-') && k !== CORE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(pageNetworkFirst(event, url));
  } else if (url.pathname.startsWith('/_astro/') || url.pathname.startsWith('/vendor/')) {
    event.respondWith(cacheFirst(request, CORE));
  } else if (url.pathname.startsWith('/nen-ban-do/') || url.pathname.startsWith('/anh/')) {
    event.respondWith(cacheFirst(request, LAZY, event));
  } else {
    event.respondWith(staleWhileRevalidate(event, request));
  }
});

// Fresh page when the network answers quickly; the saved copy otherwise.
async function pageNetworkFirst(event, url) {
  const cache = await caches.open(CORE);
  const network = fetch(event.request).then((response) => {
    if (response.ok) cache.put(url.pathname, response.clone());
    return response;
  });
  event.waitUntil(network.catch(() => undefined));
  const timeout = new Promise((resolve) => setTimeout(resolve, NETWORK_TIMEOUT));
  try {
    const response = await Promise.race([network, timeout]);
    if (response) return response;
  } catch {
    // Offline: fall through to the cache.
  }
  const saved = (await cache.match(url.pathname)) ?? (await cache.match(event.request, { ignoreSearch: true }));
  if (saved) return unredirect(saved);
  try {
    return await network;
  } catch {
    const notFound = await cache.match('/404.html');
    if (notFound) return unredirect(notFound, 404);
    return new Response('WGo đang offline.', { status: 503, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  }
}

// Browsers refuse a redirected response for a page load (Pages redirects /404.html → /404).
async function unredirect(response, status = response.status) {
  if (!response.redirected && status === response.status) return response;
  return new Response(await response.blob(), { status, statusText: response.statusText, headers: response.headers });
}

async function cacheFirst(request, cacheName, event) {
  const cache = await caches.open(cacheName);
  const saved = await cache.match(request);
  if (saved) return saved;
  const response = await fetch(request);
  if (response.ok) {
    await cache.put(request, response.clone());
    if (event && cacheName === LAZY) event.waitUntil(trim(cache));
  }
  return response;
}

async function staleWhileRevalidate(event, request) {
  const cache = await caches.open(CORE);
  const saved = await cache.match(request, { ignoreSearch: true });
  const network = fetch(request).then((response) => {
    if (response.ok) cache.put(request, response.clone());
    return response;
  });
  if (saved) {
    event.waitUntil(network.catch(() => undefined));
    return saved;
  }
  return network;
}

async function trim(cache) {
  const keys = await cache.keys();
  const extra = keys.length - LAZY_MAX_ENTRIES;
  for (let i = 0; i < extra; i++) await cache.delete(keys[i]);
}
